<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage } from 'element-plus'
import { createSeoCompetitor,createSeoCompetitorEvent,fetchSeoCompetitors,fetchSeoKeywords } from '../../api/seo'
import { currentTenantId,session } from '../../store/session'
const loading=ref(false),saving=ref(false),error=ref(''),tab=ref('ranking'),data=ref({items:[],events:[]}),keywords=ref([]),dialog=ref(false),eventDialog=ref(false),eventTarget=ref(null),form=reactive({name:'',domain:'',notes:''}),eventForm=reactive({event_type:'content',title:'',url:'',source_url:'',summary:'',event_at:''})
const canEdit=computed(()=>!session.isLoggedIn||session.canEdit('seo.competitors')),highGaps=computed(()=>keywords.value.filter(i=>!i.landing_page||i.latest_rank>20).slice(0,5))
async function load(){if(!currentTenantId.value){error.value='请先选择客户';return}loading.value=true;try{const [a,b]=await Promise.all([fetchSeoCompetitors({tenantId:currentTenantId.value}),fetchSeoKeywords({tenantId:currentTenantId.value,engine:'baidu',pageSize:100})]);data.value=a;keywords.value=b.items;error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(){if(!form.name||!form.domain)return ElMessage.warning('请填写竞品名称和域名');saving.value=true;try{await createSeoCompetitor({tenant_id:currentTenantId.value,...form,notes:form.notes||null});dialog.value=false;Object.assign(form,{name:'',domain:'',notes:''});ElMessage.success('竞品已加入监控');await load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
function openEvent(row){eventTarget.value=row;Object.assign(eventForm,{event_type:'content',title:'',url:'',source_url:'',summary:'',event_at:''});eventDialog.value=true}
async function saveEvent(){saving.value=true;try{await createSeoCompetitorEvent({tenant_id:currentTenantId.value,competitor_id:eventTarget.value.id,...eventForm,event_at:eventForm.event_at?new Date(eventForm.event_at).toISOString():null,source_url:eventForm.source_url||null,summary:eventForm.summary||null,title:eventForm.title||null});eventDialog.value=false;ElMessage.success('竞品动态已记录');await load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
watch(currentTenantId,load);onMounted(load)
</script>
<template><div class="keyword-assets competitor-prototype" v-loading="loading"><section class="kw-hero"><div><div class="kw-kicker">Competitive landscape</div><h2>竞品表现</h2><p>在同一批核心关键词下比较自然排名与可见度，同时跟踪竞品新内容和外链动态。</p></div><div class="kw-actions"><button v-if="canEdit" class="kw-btn" @click="dialog=true">＋ 添加竞品</button><button class="kw-btn primary" @click="load">生成对比报告</button></div></section><el-alert v-if="error" :title="error" type="warning" :closable="false"/><div class="kw-competitor-strip"><article class="kw-domain-card mine"><div class="domain"><span class="favicon">我</span><div>我的网站<small>当前客户站点</small></div></div><strong>{{keywords.filter(i=>i.latest_rank!=null).length}}</strong><small>已有排名关键词</small></article><article v-for="item in data.items.slice(0,3)" :key="item.id" class="kw-domain-card"><div class="domain"><span class="favicon">{{item.name.slice(0,1)}}</span><div>{{item.name}}<small>{{item.domain}}</small></div></div><strong>{{(item.content||0)+(item.backlink||0)}}</strong><small>已记录内容/外链动态</small></article></div><section class="kw-card"><header class="kw-card-head"><div><h3>{{tab==='ranking'?'核心词排名对标':'竞品内容 / 外链动态'}}</h3><p>{{tab==='ranking'?'百度桌面端 · 全国 · 最近快照':'来自人工记录和后续采集接口'}}</p></div><div class="kw-segment"><button :class="{active:tab==='ranking'}" @click="tab='ranking'">排名对比</button><button :class="{active:tab==='events'}" @click="tab='events'">内容 / 外链动态</button></div></header><div v-if="tab==='ranking'" class="kw-table-wrap"><table class="kw-table"><thead><tr><th>关键词</th><th>我的网站</th><th v-for="item in data.items.slice(0,3)" :key="item.id">{{item.name}}</th><th>竞争状态</th></tr></thead><tbody><tr v-for="item in keywords.slice(0,12)" :key="item.id"><td class="keyword-cell"><span class="kw-name">{{item.keyword}}</span><small class="kw-sub">{{item.cluster||'未归类'}}</small></td><td><span class="kw-rank"><strong>{{item.latest_rank||'100+'}}</strong></span></td><td v-for="competitor in data.items.slice(0,3)" :key="competitor.id"><span class="kw-pill gray">待采集</span></td><td><span class="kw-pill" :class="!item.landing_page||item.latest_rank>20?'red':'green'">{{!item.landing_page?'待建页':item.latest_rank>20?'需追赶':'已覆盖'}}</span></td></tr><tr v-if="!keywords.length"><td :colspan="3+data.items.slice(0,3).length"><div class="kw-empty">暂无关键词排名数据</div></td></tr></tbody></table></div><div v-else class="event-list"><article v-for="event in data.events" :key="event.id"><span class="kw-pill" :class="event.event_type==='backlink'?'orange':'blue'">{{event.event_type==='backlink'?'新外链':'新内容'}}</span><div><b>{{event.title||event.url}}</b><small>{{event.summary||event.source_url||event.url}}</small></div></article><div v-if="!data.events.length" class="kw-empty">暂无竞品动态</div></div></section><div class="kw-grid-equal lower"><section class="kw-card"><header class="kw-card-head"><div><h3>最大内容缺口</h3><p>本站覆盖不足的高价值搜索入口</p></div></header><div class="kw-card-body"><div class="kw-alert-list"><div v-for="item in highGaps" :key="item.id" class="kw-alert"><span class="mark">{{item.priority}}</span><div><h4>{{item.keyword}}</h4><p>{{item.landing_page?`当前排名 #${item.latest_rank||'100+'}`:'本站缺少承接页'}}</p></div><time>{{item.monthly_volume||'—'}}</time></div><div v-if="!highGaps.length" class="kw-empty">暂无明显内容缺口</div></div></div></section><section class="kw-card"><header class="kw-card-head"><div><h3>竞品资产</h3><p>维护域名并登记新内容和外链</p></div></header><div class="kw-card-body"><div class="kw-alert-list"><div v-for="item in data.items" :key="item.id" class="kw-alert"><span class="mark blue">{{item.name.slice(0,1)}}</span><div><h4>{{item.name}}</h4><p>{{item.domain}}</p></div><button v-if="canEdit" class="kw-btn small" @click="openEvent(item)">记录动态</button></div><div v-if="!data.items.length" class="kw-empty">尚未添加竞品</div></div></div></section></div>
<el-dialog v-model="dialog" title="添加竞品" width="560px"><el-form label-position="top"><el-form-item label="竞品名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="域名"><el-input v-model="form.domain"/></el-form-item><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="eventDialog" title="记录竞品动态" width="650px"><el-form label-position="top"><el-form-item label="类型"><el-select v-model="eventForm.event_type"><el-option label="新内容" value="content"/><el-option label="新外链" value="backlink"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="eventForm.title"/></el-form-item><el-form-item label="目标 URL"><el-input v-model="eventForm.url"/></el-form-item><el-form-item label="摘要"><el-input v-model="eventForm.summary" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="eventDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEvent">保存</el-button></template></el-dialog></div></template>
<style>@import url('/deal-sniper-prototype/seo/assets/keyword-assets-v2.css');</style>
<style scoped>.competitor-prototype{min-height:100%;padding:22px 26px 30px;background:#f5f7fb}.lower{margin-top:15px}.event-list article{padding:14px 17px;display:flex;align-items:center;gap:12px;border-bottom:1px solid #e8eaf0}.event-list b,.event-list small{display:block}.event-list small{margin-top:4px;color:#7b8494}.blue{color:#2853b6!important;background:#edf2ff!important}</style>
